// DocumentLibrary/DocumentService.cs
public class DocumentService
{
    public string LastTitle { get; private set; } = "None";
    public string Publish(string title)
    {
        LastTitle = Normalize(title);
        return FormatLabel(LastTitle);
    }
    protected virtual string FormatLabel(string title) => $"Published: {title}";
    private static string Normalize(string title) => title.Trim();
}

internal sealed class InternalDocumentFormatter { }

public sealed class BrandedDocumentService : DocumentService
{
    protected override string FormatLabel(string title) => $"Library | {title}";
}

// Runner/Program.cs
var service = new BrandedDocumentService();
Console.WriteLine(service.Publish("  Annual Report  "));
Console.WriteLine(service.LastTitle);
